def parse_env_line(line):
    if not line or line.lstrip().startswith('#'):
        return None
    if '=' not in line:
        return None
    key, value = line.split('=', 1)
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in '\"\'':
        value = value[1:-1]
    return key.strip(), value

